/* Local, synthetic cohort practice. Candidate IDs are not RFID or herd IDs. */
(function(){
const copy=x=>structuredClone(x);
const model={
 create(){return {revision:1,rows:Array.from({length:100},(_,i)=>({id:'EXAMPLE-'+String(i+1).padStart(3,'0'),recommendation:i<70?'selected':'on_hold',decision:'pending',boarding:'pending',arrival:'pending',tag:'',history:[]})),feed:{ration:null,travelDays:3,warmupDays:10,packed:null},vaccine:{plan:'vaccination.matrix',version:9,status:'published',confirmed:false},proof:{},transition:''};},
 decide(data,id,phase,value,role,reason=''){if(role!=='CEO / CXO')throw Error('CEO / CXO approval is required for this practice decision.');const r=data.rows.find(r=>r.id===id);if(!r)throw Error('Animal not found.');if(phase==='decision'){if(!['approved','rejected','pending'].includes(value))throw Error('Invalid decision.');if(r.boarding!=='pending'||r.arrival!=='pending')throw Error('Keep completed transport history; start a new practice to revise earlier selection.');}else if(phase==='boarding'){if(r.decision!=='approved')throw Error('Only selected animals can be reviewed for boarding.');if(!['boarded','held','rejected'].includes(value))throw Error('Choose boarded, held or rejected.');if(r.arrival!=='pending')throw Error('Arrival is already recorded.');if(value==='boarded'&&!r.tag.trim())throw Error('Record this animal’s actual tag before boarding.');}else if(phase==='arrival'){if(r.boarding!=='boarded')throw Error('Only boarded animals can be reconciled at arrival.');if(!['received','missing'].includes(value))throw Error('Choose received or missing.');}else throw Error('Invalid stage.');if(['rejected','held','missing'].includes(value)&&!reason.trim())throw Error('Record the reason for this exception.');r.history.push({phase,from:r[phase],to:value,reason,revision:++data.revision});r[phase]=value;},
 counts(data){return {offered:data.rows.length,selected:data.rows.filter(r=>r.decision==='approved').length,boarded:data.rows.filter(r=>r.boarding==='boarded').length,received:data.rows.filter(r=>r.arrival==='received').length};},
 feed(data){const f=data.feed;if(f.rations?.length){const boarded=new Set(data.rows.filter(r=>r.boarding==='boarded').map(r=>r.id)),seen=new Set(),covered=new Set();if(!boarded.size)throw Error('Finalize the boarding group first.');if(!Number.isFinite(f.travelDays)||f.travelDays<0||!Number.isFinite(f.warmupDays)||f.warmupDays<0)throw Error('Use valid travel and warm-up days.');const days=f.travelDays+f.warmupDays,groups=f.rations.map(row=>{if(!row.feed?.trim()||!Number.isFinite(row.ration)||row.ration<=0||!row.animalIds?.length||new Set(row.animalIds).size!==row.animalIds.length)throw Error('Each feed row needs a name, positive ration and unique candidate references.');for(const id of row.animalIds){if(!boarded.has(id))throw Error('Feed groups may contain only boarded candidates.');const key=row.feed.trim().toLowerCase()+'|'+id;if(seen.has(key))throw Error('An animal is assigned twice to the same feed.');seen.add(key);covered.add(id);}const required=Math.round(row.animalIds.length*row.ration*days*1000)/1000;return {...row,required,sufficient:typeof row.packed==='number'&&Number.isFinite(row.packed)&&row.packed>=required};});if([...boarded].some(id=>!covered.has(id)))throw Error('Assign familiar feed for every boarded candidate.');return {count:boarded.size,days,groups,required:groups.reduce((sum,g)=>sum+g.required,0),sufficient:groups.every(g=>g.sufficient)};}const count=this.counts(data).boarded;if(!count)throw Error('Finalize the boarding group first.');if(!Number.isFinite(f.ration)||f.ration<=0)throw Error('Enter the applicable daily familiar-feed ration in kg per animal.');if(!Number.isFinite(f.travelDays)||f.travelDays<0||!Number.isFinite(f.warmupDays)||f.warmupDays<0)throw Error('Use valid travel and warm-up days.');return {count,days:f.travelDays+f.warmupDays,required:Math.round(count*f.ration*(f.travelDays+f.warmupDays)*1000)/1000};}
};window.ProcurementPracticeModel=model;
function owner(){return compositionWorkflows().find(e=>e.workflow.exampleKey==='procurement-master-v1')?.workflow;}
function data(){state.procurementPractice??=model.create();return state.procurementPractice;}
model.invalidate=function(run,roots){if(!run)return;const affected=new Set(roots);let changed=true;while(changed){changed=false;for(const stage of run.definition.stagePlan.stages)if(!affected.has(stage.id)&&(stage.dependencies||[]).some(d=>affected.has(d.stageId))){affected.add(stage.id);changed=true;}}for(const id of affected)if(run.stages[id]){const old=run.stages[id],isRoot=roots.includes(id);run.stages[id]=isRoot&&old.status!=='waiting'?{status:'started',startedAt:old.startedAt,approved:false,childDone:false,checks:old.checks||[]}:{status:'waiting',approved:false,childDone:false,checks:[]};}return [...affected];};
function invalidate(roots=[]){const w=owner(),run=state.compositionPractices?.[w?.workflowId];model.invalidate(run,roots);persist();}
let phase='decision',page=0;
window.openProcurementPractice=function(next=phase){phase=next;const d=data(),counts=model.counts(d),rows=d.rows.filter(r=>phase==='decision'||phase==='boarding'&&r.decision==='approved'||phase==='arrival'&&r.boarding==='boarded'),pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages-1);const options=phase==='decision'?['pending','approved','rejected']:phase==='boarding'?['pending','boarded','held','rejected']:['pending','received','missing'];modal('Procurement · animal review and supplies',`<p class="notice">Synthetic example: 100 animals offered, target 70. These are local candidate references, not real animals or RFID tags. Changed records reopen only the affected stages and their dependents. Completed earlier stages remain intact.</p><div class="flowmini"><b>${counts.offered} offered</b>→<b>${counts.selected} selected</b>→<b>${counts.boarded} boarded</b>→<b>${counts.received} received</b></div><div class="actions"><button onclick="openProcurementPractice('decision')">Seller selection</button><button onclick="openProcurementPractice('boarding')">Boarding review</button><button onclick="openProcurementPractice('arrival')">Arrival review</button><button onclick="procurementSupplies()">Feed, vaccination & evidence</button></div><p>Field recommendation and CEO decision are separate. Review every offered animal; only approved animals appear in boarding, and only boarded animals appear at arrival. The existing inspection questions are available in the Seller inspection child SOP.</p><div class="tablewrap"><table class="cohort-table"><thead><tr><th>Candidate</th><th>Field recommendation</th><th>Tag / RFID</th><th>This review</th><th>Reason / record</th></tr></thead><tbody>${rows.slice(page*10,page*10+10).map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.recommendation)}</td><td><input aria-label="Tag ${r.id}" id="tag-${r.id}" value="${esc(r.tag)}" placeholder="Actual identifier" ${canEdit()?'':'disabled'}></td><td><select aria-label="Decision ${r.id}" id="decision-${r.id}" ${canEdit()?'':'disabled'}>${options.map(v=>`<option ${r[phase]===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input aria-label="Reason ${r.id}" id="reason-${r.id}" placeholder="Required for exceptions" ${canEdit()?'':'disabled'}><button onclick="procurementSaveAnimal('${r.id}')" ${canEdit()?'':'disabled'}>Save review</button><details><summary>History (${r.history.length})</summary>${r.history.map(h=>`<p>${esc(h.phase)}: ${esc(h.from)} → ${esc(h.to)} ${esc(h.reason)}</p>`).join('')||'No decision yet'}</details></td></tr>`).join('')}</tbody></table></div><div class="actions"><button onclick="procurementCohortPage(-1)" ${page?'':'disabled'}>Previous</button><span>Page ${page+1} of ${pages}</span><button onclick="procurementCohortPage(1)" ${page+1<pages?'':'disabled'}>Next</button></div>${phase==='decision'?`<details><summary>Load a worked example</summary><p>Explicitly fills synthetic decisions: first 70 approved and remaining 30 rejected as outside the sample target. No real inspection evidence is implied. Existing recorded decisions are kept.</p><button onclick="procurementSampleSelection()" ${canEdit()?'':'disabled'}>Use sample 70 / 100 selection</button></details>`:''}<p id="cohort-error" role="status"></p>`,true);};
window.procurementCohortPage=function(delta){page=Math.max(0,page+delta);openProcurementPractice();};
window.procurementSaveAnimal=function(id){if(!canEdit())return;try{const d=data(),r=d.rows.find(r=>r.id===id),tag=$('#tag-'+id).value.trim(),old=r.tag,oldPhase=r[phase];if(r.boarding==='boarded'&&tag!==old)throw Error('Keep the boarded animal identifier; start a new practice to correct its identity.');if(d.rows.some(x=>x.id!==id&&tag&&x.tag===tag))throw Error('This tag is already assigned to another candidate.');r.tag=tag;try{model.decide(d,id,phase,$('#decision-'+id).value,$('#role').value,$('#reason-'+id).value);}catch(e){r.tag=old;throw e;}const roots=[];if(tag!==old)roots.push('stage-1');if(r[phase]!==oldPhase)roots.push(phase==='decision'?'stage-0':phase==='boarding'?'stage-2':'stage-3');invalidate(roots);openProcurementPractice();}catch(e){$('#cohort-error').textContent=e.message;}};
window.procurementSampleSelection=function(){if(!canEdit())return;const d=data();d.rows.forEach((r,i)=>{if(r.decision==='pending')model.decide(d,r.id,'decision',i<70?'approved':'rejected','CEO / CXO',i<70?'Synthetic worked example':'Outside the sample target of 70');});invalidate(['stage-0']);openProcurementPractice();};
window.procurementSupplies=function(){const d=data(),settings=owner()?.stagePlan?.stages||[];for(const [key,stage] of [['travelDays','stage-3'],['warmupDays','stage-5']]){const s=settings.find(s=>s.id===stage),ref=s?.waitDaysRef,item=state.items.find(i=>i.configKey===ref||'config:'+i.id===ref);if(item&&typeof item.value==='number')d.feed[key]=item.value;}let calc;try{calc=model.feed(d)}catch(e){calc={error:e.message}}modal('Procurement · feed, vaccination and evidence',`<p>Use the final boarding group and the selected plan. This is a local planning example; actual rations and clinical rules stay with their departments.</p><section class="card"><h3>Familiar feed to carry</h3><p>${model.counts(d).boarded} boarded animals × daily ration × (${d.feed.travelDays} travel days + ${d.feed.warmupDays} warm-up days). Days come from this SOP’s shared settings.</p>${(d.feed.rations||[{feed:'Familiar feed',animalIds:d.rows.filter(r=>r.boarding==='boarded').map(r=>r.id),ration:d.feed.ration,packed:d.feed.packed}]).map((g,i)=>`<section class="card"><label class="field">Feed name<input id="cohort-feed-${i}" value="${esc(g.feed)}" ${canEdit()?'':'disabled'}></label><label class="field">Candidate references in this ration group (comma separated)<textarea id="cohort-animals-${i}" ${canEdit()?'':'disabled'}>${esc(g.animalIds.join(', '))}</textarea></label><div class="inputrow"><label class="field">Daily kg per animal<input id="cohort-ration-${i}" type="number" min="0" step="0.001" value="${g.ration??''}" ${canEdit()?'':'disabled'}></label><label class="field">Packed kg for this feed/group<input id="cohort-packed-${i}" type="number" min="0" step="0.001" value="${g.packed??''}" ${canEdit()?'':'disabled'}></label></div>${calc.groups?.[i]?`<p>Required: ${calc.groups[i].required} kg · ${calc.groups[i].sufficient?'Packed enough':'More feed needed'}</p>`:''}<button onclick="procurementRemoveFeed(${i})" ${canEdit()?'':'disabled'}>Remove feed row</button></section>`).join('')}<button onclick="procurementAddFeed()" ${canEdit()?'':'disabled'}>Add feed / ration group</button><p>${calc.error?esc(calc.error):`Total familiar feed: <b>${calc.required} kg</b>. Each feed must have enough packed quantity; surplus in one feed does not cover another.`}</p><p class="muted">One candidate may need several feeds. Different ration groups for the same feed must use different candidates. No ration or wastage factor is invented.</p></section><section class="card"><h3>Vaccination plan</h3><p>Reference: ${esc(d.vaccine.plan)} · published v${d.vaccine.version}. Staging’s v10 is a draft and is not selected.</p><label><input id="cohort-vax" type="checkbox" ${d.vaccine.confirmed?'checked':''} ${canEdit()?'':'disabled'}>Reviewed the applicable published plan and per-animal eligibility / prior doses</label><p>Age, purpose, dose spacing, pregnancy and clinical deferrals remain in the vaccination plan. A checkbox here is a practice acknowledgement, not vaccination evidence.</p><a href="https://dashboard.mesha.sg/vaccination/plan" target="_blank" rel="noopener">Open existing vaccination plan ↗</a></section><section class="card"><h3>Required stage evidence</h3>${[['tagging','Tagging and vaccination records'],['truck','Truck sanitation and supplies'],['sheds','Shed sanitation, water and ORS readiness']].map(([k,label])=>`<label class="field">${label}<input id="cohort-proof-${k}" type="file" accept="image/*,video/*" ${canEdit()?'':'disabled'}><small>${esc(d.proof[k]?.name||'No practice file selected')}</small></label>`).join('')}<p>Only file names and types are kept in this browser; nothing uploads.</p></section><label class="field">Approved feed transition instructions<textarea id="cohort-transition" placeholder="Reference the applicable feed plan and describe gradual introduction; no default blend ratio" ${canEdit()?'':'disabled'}>${esc(d.transition)}</textarea></label><button class="primary" onclick="procurementSaveSupplies()" ${canEdit()?'':'disabled'}>Save practice plan</button><button onclick="openProcurementPractice()">Back to animal review</button><p id="cohort-error" role="status"></p>`,true);};
function readFeedRows(d){const existing=d.feed.rations||[{}];return existing.map((g,i)=>{const number=id=>{const e=$(id);if(e.validity?.badInput||e.value.trim()!==''&&(!Number.isFinite(Number(e.value))||Number(e.value)<0))throw Error('Use valid non-negative feed quantities.');return e.value.trim()===''?null:Number(e.value);};return {feed:$('#cohort-feed-'+i).value.trim(),animalIds:$('#cohort-animals-'+i).value.split(',').map(s=>s.trim()).filter(Boolean),ration:number('#cohort-ration-'+i),packed:number('#cohort-packed-'+i)};});}
window.procurementAddFeed=function(){if(!canEdit())return;try{const d=data();d.feed.rations=readFeedRows(d);d.feed.rations.push({feed:'',animalIds:d.rows.filter(r=>r.boarding==='boarded').map(r=>r.id),ration:null,packed:null});invalidate(['stage-2']);procurementSupplies();}catch(e){$('#cohort-error').textContent=e.message;}};
window.procurementRemoveFeed=function(index){if(!canEdit())return;try{const d=data();d.feed.rations=readFeedRows(d);if(d.feed.rations.length<2)throw Error('Keep at least one feed row.');d.feed.rations.splice(index,1);invalidate(['stage-2']);procurementSupplies();}catch(e){$('#cohort-error').textContent=e.message;}};
window.procurementSaveSupplies=function(){if(!canEdit())return;try{const d=data(),before=copy(d),groups=readFeedRows(d);const proofs={...d.proof};for(const k of ['tagging','truck','sheds']){const f=$('#cohort-proof-'+k).files?.[0];if(f){if(!/^(image|video)\//.test(f.type))throw Error('Choose a photo or video.');proofs[k]={name:f.name,type:f.type};}}d.feed.rations=groups;d.vaccine.confirmed=$('#cohort-vax').checked;d.proof=proofs;d.transition=$('#cohort-transition').value.trim();const roots=[];if(before.vaccine.confirmed!==d.vaccine.confirmed||JSON.stringify(before.proof.tagging)!==JSON.stringify(d.proof.tagging))roots.push('stage-1');if(JSON.stringify(before.feed)!==JSON.stringify(d.feed)||JSON.stringify(before.proof.truck)!==JSON.stringify(d.proof.truck))roots.push('stage-2');if(JSON.stringify(before.proof.sheds)!==JSON.stringify(d.proof.sheds))roots.push('stage-4');if(before.transition!==d.transition)roots.push('stage-5');invalidate(roots);procurementSupplies();}catch(e){$('#cohort-error').textContent=e.message;}};
window.compositionBusinessGuard=function(action,run,id){const w=owner();if(!w||run.definition.workflowId!==w.workflowId)return '';if(!['approve','finish'].includes(action))return '';const d=data(),c=model.counts(d);if(id==='stage-0'&&(!c.selected||d.rows.some(r=>r.decision==='pending')))return 'Review all offered candidates in Animal review and supplies before approving selection.';if(id==='stage-1'&&(!d.vaccine.confirmed||!d.proof.tagging||d.rows.some(r=>r.decision==='approved'&&!r.tag)))return 'Record tags, plan review and practice vaccination evidence for the selected group.';if(id==='stage-2'){if(!c.boarded||d.rows.some(r=>r.decision==='approved'&&r.boarding==='pending'))return 'Finalize every selected animal’s boarding decision first.';if(!d.proof.truck)return 'Record truck sanitation and supply evidence.';try{const pinned=run.definition.stagePlan?.stages||[];const calc=model.feed({...d,feed:{...d.feed,travelDays:pinned.find(s=>s.id==='stage-3')?.waitDays??d.feed.travelDays,warmupDays:pinned.find(s=>s.id==='stage-5')?.waitDays??d.feed.warmupDays}});if(calc.groups?!calc.sufficient:d.feed.packed<calc.required)return 'Packed feed is below the required amount.';}catch(e){return e.message;}}if(id==='stage-3'&&d.rows.some(r=>r.boarding==='boarded'&&r.arrival==='pending'))return 'Reconcile every boarded animal at arrival.';if(id==='stage-4'&&!d.proof.sheds)return 'Record destination shed readiness evidence.';if(id==='stage-5'&&(!c.received||!d.transition))return 'Confirm the received group and record the approved feed transition instructions.';return '';};
const previous=renderEditor;renderEditor=function(){previous();if(sop().exampleKey==='procurement-master-v1')$('.toolbar')?.insertAdjacentHTML('beforeend','<button onclick="openProcurementPractice()">Animal review and supplies</button>');};
})();
